package com.erikjere.mouseclickguard;

/**
 * {@link ButtonStats} for the left and right button over the same period.
 */
class ButtonPair
{
	private ButtonStats left = new ButtonStats();
	private ButtonStats right = new ButtonStats();

	ButtonStats get(MouseButton button)
	{
		return button == MouseButton.LEFT ? left : right;
	}

	void record(PressEvent event)
	{
		get(event.getButton()).record(event);
	}

	void add(ButtonPair other)
	{
		left.add(other.left);
		right.add(other.right);
	}

	ButtonPair copy()
	{
		ButtonPair copy = new ButtonPair();
		copy.left = left.copy();
		copy.right = right.copy();
		return copy;
	}

	void normalize()
	{
		if (left == null)
		{
			left = new ButtonStats();
		}
		if (right == null)
		{
			right = new ButtonStats();
		}
		left.normalize();
		right.normalize();
	}
}

package com.erikjere.mouseclickguard;

/**
 * Counts and a Press interval histogram for one button over one period.
 */
class ButtonStats
{
	static final int BIN_WIDTH_MS = 10;
	/**
	 * 20 bins of 10 ms covering 0-199 ms, plus one overflow bin.
	 */
	static final int BINS = 21;

	private Counts counts = new Counts();
	private long[] histogram = new long[BINS];

	void record(PressEvent event)
	{
		counts.record(event);
		if (event.hasInterval())
		{
			histogram[(int) Math.min(event.getIntervalMs() / BIN_WIDTH_MS, BINS - 1)]++;
		}
	}

	Counts getCounts()
	{
		return counts;
	}

	long[] getHistogram()
	{
		return histogram;
	}

	void add(ButtonStats other)
	{
		counts.add(other.counts);
		for (int i = 0; i < BINS; i++)
		{
			histogram[i] += other.histogram[i];
		}
	}

	ButtonStats copy()
	{
		ButtonStats copy = new ButtonStats();
		copy.counts = counts.copy();
		copy.histogram = histogram.clone();
		return copy;
	}

	/**
	 * Repairs instances deserialized from older or hand-edited data.
	 */
	void normalize()
	{
		if (counts == null)
		{
			counts = new Counts();
		}
		if (histogram == null || histogram.length != BINS)
		{
			histogram = new long[BINS];
		}
	}
}

package com.erikjere.mouseclickguard;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * Decides which chat warnings to show: a Chatter summary per button at most once per {@link #THROTTLE_MS}, and a
 * message whenever a button's Mouse health changes to a known verdict.
 */
class ChatWarnings
{
	static final long THROTTLE_MS = 5 * 60_000;

	private final Map<MouseButton, Counts> pending = new EnumMap<>(MouseButton.class);
	private final Map<MouseButton, Long> lastWarning = new EnumMap<>(MouseButton.class);
	private final Map<MouseButton, MouseHealth> health = new EnumMap<>(MouseButton.class);
	private final List<String> healthMessages = new ArrayList<>();

	synchronized void onPress(PressEvent event)
	{
		if (event.isChatter())
		{
			pending.computeIfAbsent(event.getButton(), b -> new Counts()).record(event);
		}
	}

	synchronized void onHealth(MouseButton button, MouseHealth current)
	{
		MouseHealth previous = health.put(button, current);
		if (previous != null && previous != current && current != MouseHealth.UNKNOWN)
		{
			healthMessages.add(String.format("Mouse Click Guard: %s button health changed from %s to %s.",
				button.getDisplayName(), previous.getDisplayName(), current.getDisplayName()));
		}
	}

	synchronized List<String> poll(long now)
	{
		List<String> messages = new ArrayList<>(healthMessages);
		healthMessages.clear();
		for (MouseButton button : MouseButton.values())
		{
			Counts counts = pending.get(button);
			Long last = lastWarning.get(button);
			if (counts == null || (last != null && now - last < THROTTLE_MS))
			{
				continue;
			}
			messages.add(String.format("Mouse Click Guard: %d chatter press%s on the %s button (%d suppressed).",
				counts.getChatter(), counts.getChatter() == 1 ? "" : "es", button.getDisplayName(), counts.getSuppressed()));
			pending.remove(button);
			lastWarning.put(button, now);
		}
		return messages;
	}

	synchronized void clearPending()
	{
		pending.clear();
	}
}

package com.erikjere.mouseclickguard;

import java.awt.event.MouseEvent;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.IntSupplier;
import java.util.function.Predicate;
import net.runelite.client.input.MouseAdapter;

/**
 * Feeds Presses to the {@link PressDetector}s and, for a Suppressed press, also consumes the release and click
 * events that belong to it so the game never sees half of a click. Only consumes events, never creates them.
 */
class ClickGuardMouseListener extends MouseAdapter
{
	private final IntSupplier thresholdMs;
	private final Predicate<MouseButton> preventionEnabled;
	private final Consumer<PressEvent> sink;

	private final Map<MouseButton, PressDetector> detectors = new EnumMap<>(MouseButton.class);
	private final Set<MouseButton> swallowRelease = EnumSet.noneOf(MouseButton.class);
	private final Set<MouseButton> swallowClick = EnumSet.noneOf(MouseButton.class);

	ClickGuardMouseListener(IntSupplier thresholdMs, Predicate<MouseButton> preventionEnabled, Consumer<PressEvent> sink)
	{
		this.thresholdMs = thresholdMs;
		this.preventionEnabled = preventionEnabled;
		this.sink = sink;
		for (MouseButton button : MouseButton.values())
		{
			detectors.put(button, new PressDetector(button));
		}
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event)
	{
		MouseButton button = MouseButton.of(event);
		if (button == null)
		{
			return event;
		}
		// A click event only follows a release when the mouse did not move, so a pending one may never arrive.
		swallowClick.remove(button);

		PressEvent press = detectors.get(button).onPress(event.getWhen(), thresholdMs.getAsInt(), preventionEnabled.test(button));
		sink.accept(press);
		if (press.isSuppressed())
		{
			swallowRelease.add(button);
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event)
	{
		MouseButton button = MouseButton.of(event);
		if (button != null && swallowRelease.remove(button))
		{
			swallowClick.add(button);
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event)
	{
		MouseButton button = MouseButton.of(event);
		if (button != null && swallowClick.remove(button))
		{
			event.consume();
		}
		return event;
	}
}

package com.erikjere.mouseclickguard;

import java.time.LocalDate;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import lombok.Value;

/**
 * Session and daily statistics for all tracked buttons. Thread-safe: presses are recorded on the AWT
 * event thread while persistence and chat warnings run elsewhere.
 */
class ClickStatistics
{
	static final int RETENTION_DAYS = 90;
	static final int HEALTH_WINDOW_DAYS = 7;
	static final int RECENT_EVENTS = 50;

	private ButtonPair session = new ButtonPair();
	private final TreeMap<LocalDate, ButtonPair> daily = new TreeMap<>();
	/**
	 * Most recent Chatter presses, newest first.
	 */
	private final Deque<PressEvent> recent = new ArrayDeque<>();
	private boolean dirty;

	synchronized void record(PressEvent event, LocalDate today)
	{
		session.record(event);
		daily.computeIfAbsent(today, d -> new ButtonPair()).record(event);
		if (event.isChatter())
		{
			recent.addFirst(event);
			while (recent.size() > RECENT_EVENTS)
			{
				recent.removeLast();
			}
		}
		prune(today);
		dirty = true;
	}

	/**
	 * Mouse health over the last {@link #HEALTH_WINDOW_DAYS} days, so the verdict follows the current state of the
	 * mouse rather than its whole history.
	 */
	synchronized MouseHealth health(MouseButton button, LocalDate today)
	{
		Counts counts = window(today, HEALTH_WINDOW_DAYS).get(button).getCounts();
		return MouseHealth.of(counts.getPresses(), counts.getChatter());
	}

	/**
	 * Sum of the last {@code days} days, today included.
	 */
	private ButtonPair window(LocalDate today, int days)
	{
		ButtonPair sum = new ButtonPair();
		for (ButtonPair day : daily.subMap(today.minusDays(days - 1), true, today, true).values())
		{
			sum.add(day);
		}
		return sum;
	}

	synchronized void reset()
	{
		session = new ButtonPair();
		daily.clear();
		recent.clear();
		dirty = true;
	}

	synchronized Snapshot snapshot(LocalDate today)
	{
		TreeMap<LocalDate, ButtonPair> dailyCopy = new TreeMap<>();
		daily.forEach((date, pair) -> dailyCopy.put(date, pair.copy()));
		return new Snapshot(
			session.copy(),
			window(today, HEALTH_WINDOW_DAYS),
			window(today, RETENTION_DAYS),
			Collections.unmodifiableNavigableMap(dailyCopy.descendingMap()),
			Collections.unmodifiableList(new ArrayList<>(recent)),
			health(MouseButton.LEFT, today),
			health(MouseButton.RIGHT, today));
	}

	/**
	 * @return true if anything changed since the last call
	 */
	synchronized boolean takeDirty()
	{
		boolean wasDirty = dirty;
		dirty = false;
		return wasDirty;
	}

	synchronized Persisted toPersisted()
	{
		Persisted persisted = new Persisted();
		daily.forEach((date, pair) -> persisted.daily.put(date.toString(), pair.copy()));
		return persisted;
	}

	synchronized void restore(Persisted persisted)
	{
		daily.clear();
		if (persisted.daily != null)
		{
			for (Map.Entry<String, ButtonPair> entry : persisted.daily.entrySet())
			{
				ButtonPair pair = entry.getValue();
				if (pair != null)
				{
					pair.normalize();
					daily.put(LocalDate.parse(entry.getKey()), pair);
				}
			}
		}
	}

	private void prune(LocalDate today)
	{
		daily.headMap(today.minusDays(RETENTION_DAYS - 1)).clear();
	}

	@Value
	static class Snapshot
	{
		ButtonPair session;
		ButtonPair last7Days;
		ButtonPair last90Days;
		/**
		 * Newest day first.
		 */
		NavigableMap<LocalDate, ButtonPair> daily;
		List<PressEvent> recent;
		MouseHealth leftHealth;
		MouseHealth rightHealth;

		MouseHealth getHealth(MouseButton button)
		{
			return button == MouseButton.LEFT ? leftHealth : rightHealth;
		}
	}

	/**
	 * Stored form. The session is deliberately not persisted. Version 1 also had an all-time total, which is
	 * ignored when read.
	 */
	static class Persisted
	{
		int version = 2;
		Map<String, ButtonPair> daily = new TreeMap<>();
	}
}

package com.erikjere.mouseclickguard;

import lombok.Getter;

@Getter
class Counts
{
	private long presses;
	private long chatter;
	private long suppressed;

	void record(PressEvent event)
	{
		presses++;
		if (event.isChatter())
		{
			chatter++;
		}
		if (event.isSuppressed())
		{
			suppressed++;
		}
	}

	void add(Counts other)
	{
		presses += other.presses;
		chatter += other.chatter;
		suppressed += other.suppressed;
	}

	Counts copy()
	{
		Counts copy = new Counts();
		copy.add(this);
		return copy;
	}
}

package com.erikjere.mouseclickguard;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Bar chart of Press intervals; bars below the Chatter threshold are drawn in red.
 */
class IntervalHistogram extends JComponent
{
	private static final int HEIGHT = 70;
	private static final int AXIS_HEIGHT = 14;
	private static final Color CHATTER_COLOR = ColorScheme.PROGRESS_ERROR_COLOR;
	private static final Color NORMAL_COLOR = ColorScheme.LIGHT_GRAY_COLOR;

	private long[] bins = new long[ButtonStats.BINS];
	private int thresholdMs;

	IntervalHistogram()
	{
		setPreferredSize(new Dimension(0, HEIGHT));
		setFont(FontManager.getRunescapeSmallFont());
		setToolTipText("");
	}

	void update(long[] bins, int thresholdMs)
	{
		this.bins = bins;
		this.thresholdMs = thresholdMs;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics;
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(ColorScheme.DARKER_GRAY_COLOR);
		g.fillRect(0, 0, getWidth(), getHeight());

		long max = 1;
		for (long bin : bins)
		{
			max = Math.max(max, bin);
		}

		int chartHeight = getHeight() - AXIS_HEIGHT;
		double barWidth = (double) getWidth() / bins.length;
		for (int i = 0; i < bins.length; i++)
		{
			int barHeight = (int) Math.round((double) bins[i] / max * (chartHeight - 2));
			if (bins[i] > 0 && barHeight == 0)
			{
				barHeight = 1;
			}
			int x = (int) Math.round(i * barWidth);
			int w = Math.max(1, (int) Math.round((i + 1) * barWidth) - x - 1);
			g.setColor(isChatterBin(i) ? CHATTER_COLOR : NORMAL_COLOR);
			g.fillRect(x, chartHeight - barHeight, w, barHeight);
		}

		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		FontMetrics metrics = g.getFontMetrics();
		int baseline = getHeight() - 3;
		g.drawString("0", 1, baseline);
		String middle = (ButtonStats.BINS - 1) * ButtonStats.BIN_WIDTH_MS / 2 + "";
		g.drawString(middle, (getWidth() - metrics.stringWidth(middle)) / 2, baseline);
		String end = (ButtonStats.BINS - 1) * ButtonStats.BIN_WIDTH_MS + "+ ms";
		g.drawString(end, getWidth() - metrics.stringWidth(end) - 1, baseline);
	}

	@Override
	public String getToolTipText(MouseEvent event)
	{
		int i = Math.min(bins.length - 1, Math.max(0, event.getX() * bins.length / Math.max(1, getWidth())));
		int from = i * ButtonStats.BIN_WIDTH_MS;
		String range = i == bins.length - 1 ? from + "+ ms" : from + "-" + (from + ButtonStats.BIN_WIDTH_MS - 1) + " ms";
		return range + ": " + bins[i] + " presses";
	}

	private boolean isChatterBin(int i)
	{
		return i * ButtonStats.BIN_WIDTH_MS < thresholdMs;
	}
}

package com.erikjere.mouseclickguard;

import java.awt.event.MouseEvent;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
enum MouseButton
{
	LEFT("left"),
	RIGHT("right");

	private final String displayName;

	/**
	 * @return the tracked button for this event, or null for buttons that are not tracked
	 */
	static MouseButton of(MouseEvent event)
	{
		switch (event.getButton())
		{
			case MouseEvent.BUTTON1:
				return LEFT;
			case MouseEvent.BUTTON3:
				return RIGHT;
			default:
				return null;
		}
	}
}

package com.erikjere.mouseclickguard;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(MouseClickGuardConfig.GROUP)
public interface MouseClickGuardConfig extends Config
{
	String GROUP = "mouseclickguard";

	@ConfigSection(
		name = "Click prevention",
		description = "Discard chatter presses before the game sees them",
		position = 1
	)
	String preventionSection = "prevention";

	@ConfigSection(
		name = "Chat warnings",
		description = "Chat messages about chatter and mouse health",
		position = 2
	)
	String warningsSection = "warnings";

	@Range(min = 10, max = 150)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "chatterThreshold",
		name = "Chatter threshold",
		description = "A press that follows the previous press of the same button sooner than this is counted as chatter."
			+ " Deliberate fast clicking is usually above 80 ms.",
		position = 0
	)
	default int chatterThreshold()
	{
		return 50;
	}

	@ConfigItem(
		keyName = "preventLeft",
		name = "Prevent left chatter",
		description = "Discard a left press that comes sooner than the chatter threshold after the last accepted left press",
		section = preventionSection,
		position = 0
	)
	default boolean preventLeft()
	{
		return false;
	}

	@ConfigItem(
		keyName = "preventRight",
		name = "Prevent right chatter",
		description = "Discard a right press that comes sooner than the chatter threshold after the last accepted right press",
		section = preventionSection,
		position = 1
	)
	default boolean preventRight()
	{
		return false;
	}

	@ConfigItem(
		keyName = "chatWarnings",
		name = "Chat warnings",
		description = "Summarise chatter in chat at most once every 5 minutes per button, and announce mouse health changes",
		section = warningsSection,
		position = 0
	)
	default boolean chatWarnings()
	{
		return true;
	}
}

package com.erikjere.mouseclickguard;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

class MouseClickGuardPanel extends PluginPanel
{
	private static final String LAST_7_DAYS = "Last " + ClickStatistics.HEALTH_WINDOW_DAYS + " days";
	private static final String LAST_90_DAYS = "Last " + ClickStatistics.RETENTION_DAYS + " days";
	private static final String SESSION = "This session";
	private static final int RECENT_SHOWN = 20;
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm:ss").withZone(ZoneId.systemDefault());
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM");

	private final JComboBox<String> period = new JComboBox<>(new String[]{LAST_7_DAYS, LAST_90_DAYS, SESSION});
	private final Map<MouseButton, ButtonSection> sections = new EnumMap<>(MouseButton.class);
	private final JPanel recent = verticalPanel();
	private final JPanel daily = new JPanel(new GridLayout(0, 3, 4, 2));

	private ClickStatistics.Snapshot snapshot;
	private int thresholdMs;

	MouseClickGuardPanel(Runnable onReset)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBorder(new EmptyBorder(8, 8, 8, 8));

		JLabel title = new JLabel("Mouse Click Guard");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		add(row(title));

		period.addActionListener(e -> render());
		add(row(period));

		for (MouseButton button : MouseButton.values())
		{
			ButtonSection section = new ButtonSection(button);
			sections.put(button, section);
			add(section);
		}

		add(heading("Recent chatter"));
		add(recent);

		add(heading("Daily chatter per 1,000 presses"));
		daily.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(daily);

		JButton reset = new JButton("Reset statistics");
		reset.addActionListener(e ->
		{
			int answer = JOptionPane.showConfirmDialog(this,
				"Delete all Mouse Click Guard statistics, including history?",
				"Reset statistics", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
			if (answer == JOptionPane.YES_OPTION)
			{
				onReset.run();
			}
		});
		add(row(reset));
	}

	void update(ClickStatistics.Snapshot snapshot, int thresholdMs)
	{
		this.snapshot = snapshot;
		this.thresholdMs = thresholdMs;
		render();
	}

	private void render()
	{
		if (snapshot == null)
		{
			return;
		}
		ButtonPair stats = selectedPeriod();
		for (MouseButton button : MouseButton.values())
		{
			sections.get(button).update(stats.get(button), snapshot.getHealth(button), thresholdMs);
		}

		recent.removeAll();
		List<PressEvent> events = snapshot.getRecent();
		if (events.isEmpty())
		{
			recent.add(small("None yet", ColorScheme.LIGHT_GRAY_COLOR));
		}
		for (PressEvent event : events.subList(0, Math.min(RECENT_SHOWN, events.size())))
		{
			String text = String.format("%s  %s  %d ms%s", TIME.format(Instant.ofEpochMilli(event.getTimestamp())),
				capitalize(event.getButton().getDisplayName()), event.getIntervalMs(), event.isSuppressed() ? "  suppressed" : "");
			recent.add(small(text, event.isSuppressed() ? ColorScheme.PROGRESS_ERROR_COLOR : Color.WHITE));
		}

		daily.removeAll();
		daily.add(small("Day", ColorScheme.LIGHT_GRAY_COLOR));
		daily.add(small("Left", ColorScheme.LIGHT_GRAY_COLOR));
		daily.add(small("Right", ColorScheme.LIGHT_GRAY_COLOR));
		for (Map.Entry<LocalDate, ButtonPair> day : snapshot.getDaily().entrySet())
		{
			daily.add(small(DAY.format(day.getKey()), Color.WHITE));
			for (MouseButton button : MouseButton.values())
			{
				Counts counts = day.getValue().get(button).getCounts();
				daily.add(small(counts.getPresses() == 0 ? "-"
					: String.format("%.1f (%d)", MouseHealth.chatterRate(counts.getPresses(), counts.getChatter()), counts.getPresses()),
					Color.WHITE));
			}
		}

		revalidate();
		repaint();
	}

	private ButtonPair selectedPeriod()
	{
		Object selected = period.getSelectedItem();
		if (LAST_90_DAYS.equals(selected))
		{
			return snapshot.getLast90Days();
		}
		if (SESSION.equals(selected))
		{
			return snapshot.getSession();
		}
		return snapshot.getLast7Days();
	}

	private static class ButtonSection extends JPanel
	{
		private final JLabel health = new JLabel();
		private final JLabel counts = new JLabel();
		private final IntervalHistogram histogram = new IntervalHistogram();

		ButtonSection(MouseButton button)
		{
			setLayout(new BorderLayout(0, 4));
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(6, 0, 0, 0, ColorScheme.DARK_GRAY_COLOR),
				new EmptyBorder(6, 6, 6, 6)));

			JPanel header = new JPanel(new BorderLayout());
			header.setOpaque(false);
			JLabel name = new JLabel(capitalize(button.getDisplayName()) + " button");
			name.setForeground(Color.WHITE);
			header.add(name, BorderLayout.WEST);
			health.setToolTipText("Based on the last " + ClickStatistics.HEALTH_WINDOW_DAYS + " days; needs "
				+ MouseHealth.MIN_PRESSES + " presses");
			header.add(health, BorderLayout.EAST);

			counts.setFont(FontManager.getRunescapeSmallFont());
			counts.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

			add(header, BorderLayout.NORTH);
			add(counts, BorderLayout.CENTER);
			add(histogram, BorderLayout.SOUTH);
		}

		void update(ButtonStats stats, MouseHealth verdict, int thresholdMs)
		{
			health.setText(verdict.getDisplayName());
			health.setForeground(color(verdict));
			Counts c = stats.getCounts();
			counts.setText(String.format("<html>%d presses, %d chatter (%.1f / 1,000)<br>%d suppressed</html>",
				c.getPresses(), c.getChatter(), MouseHealth.chatterRate(c.getPresses(), c.getChatter()), c.getSuppressed()));
			histogram.update(stats.getHistogram(), thresholdMs);
		}

		private static Color color(MouseHealth verdict)
		{
			switch (verdict)
			{
				case HEALTHY:
					return ColorScheme.PROGRESS_COMPLETE_COLOR;
				case SUSPECT:
					return ColorScheme.PROGRESS_INPROGRESS_COLOR;
				case FAILING:
					return ColorScheme.PROGRESS_ERROR_COLOR;
